let disposeDialog=()=>{};
let heroTimer,heroIndex=0,heroPaused=false;
const heroRecipes=()=>{const photos=state.recipes.filter(r=>recipePhotos(r).length);return photos.length?photos:state.recipes.filter(r=>r.id==='egg-fried-rice')};
const heroRecipe=()=>{const list=heroRecipes();return list[heroIndex%Math.max(list.length,1)]||{name:'A taste of home',category:'rice',photo:''}};
function heroSlide(r){return `${photo(r,true)}<span class="hero-sticker">${i('sun')} A little joy<br>on your plate</span><span class="feature-caption"><span><span class="eyebrow">${tr('FROM OUR KITCHENS','ကျွန်ုပ်တို့၏ အိမ်ချက်လက်ရာများ')}</span><strong>${esc(title(r))}</strong><small>${i('clock-3')} ${r.cookTime?`${r.cookTime} min`:tr('Community recipe','မျှဝေထားသောချက်နည်း')} <span>•</span> ${esc(r.author||'Myanmar Kitchen')}</small></span><span class="round-arrow">${i('arrow-up-right')}</span></span>`}
function startHero(){
 const button=$('#today'),control=$('#hero-pause');if(!button)return;
 const reduced=matchMedia('(prefers-reduced-motion: reduce)');
 function controlText(){control.textContent=heroPaused?tr('▶ Play slideshow','▶ ပုံများ ဆက်ပြရန်'):tr('Ⅱ Pause slideshow','Ⅱ ပုံပြောင်းခြင်း ရပ်ရန်');control.setAttribute('aria-pressed',String(heroPaused))}
 if(reduced.matches)heroPaused=true;
 if(control){control.onclick=()=>{heroPaused=!heroPaused;controlText()};controlText()}
 heroTimer=setInterval(async()=>{
  if(heroPaused||document.hidden||$('#dialog').open||button.matches(':hover')||button.contains(document.activeElement)||heroRecipes().length<2)return;
  const list=heroRecipes(),nextIndex=(heroIndex+1)%list.length,next=list[nextIndex],url=recipePhotos(next)[0];
  if(url){const img=new Image();img.referrerPolicy='no-referrer';img.src=url;try{await img.decode()}catch{return}}
  if(!button.isConnected||heroPaused||document.hidden||$('#dialog').open)return;
  heroIndex=nextIndex;button.innerHTML=heroSlide(next);button.setAttribute('aria-label',tr('Open recipe: ','ချက်နည်းကြည့်ရန်: ')+title(next));iconsNow();bindImages();
  if(!reduced.matches)button.animate([{opacity:.25},{opacity:1}],{duration:1100,easing:'ease-out'});
 },6000);
}

let importDraft=null,importBusy=false,importRouteShown='',authReady=false;
const state={customCategories:[],recipes:[],user:null,favorites:new Set(),query:'',category:'all',recipeGroup:'',region:'',time:'',difficulty:'',sort:'featured',view:'discover',lang:localStorage.getItem('mykitch_lang')||'en',loading:true,error:''};
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const i=(name,cls='')=>`<i data-lucide="${name}" class="${cls}" aria-hidden="true"></i>`;
const tr=(en,my)=>state.lang==='my'?my:en;
const labels={rice:['Rice & everyday','ထမင်း'],curry:['Curries','ဟင်း'],noodle:['Noodles & soups','ခေါက်ဆွဲ'],salad:['Salads','အသုပ်'],snack:['Snacks','အဆာပြေ'],dessert:['Sweet treats','အချိုပွဲ'],drink:['Tea & drinks','အဖျော်ယမကာ'],basic:['Kitchen basics','အခြေခံ']};
const glyph={rice:'🍚',curry:'🍲',noodle:'🍜',salad:'🥗',snack:'🥟',dessert:'🍮',drink:'🍵',basic:'🧄'};
const categoryIds=()=>[...categories,...state.customCategories.map(c=>c.id)];
const categoryRecord=c=>state.customCategories.find(x=>x.id===c)||defaultCategories.find(x=>x.id===c);
const label=c=>{const r=categoryRecord(c);return r?(state.lang==='my'&&r.nameMy?r.nameMy:r.name):c};
const title=r=>state.lang==='my'&&r.nameMy?r.nameMy:r.name;
const description=r=>state.lang==='my'&&r.descriptionMy?r.descriptionMy:r.description;
const complete=r=>r.ingredients.length&&r.steps.length;
function facetValues(key){const values=new Map();for(const r of state.recipes){const value=String(r[key]||'').trim();if(value&&!values.has(normalizeName(value)))values.set(normalizeName(value),value)}return [...values.values()].sort((a,b)=>a.localeCompare(b))}
function variantBadges(r){return `<div class="variant-badges">${[['recipeGroup',r.recipeGroup],['region',r.region]].filter(([,v])=>v).map(([key,v])=>`<button type="button" data-facet="${key}" data-value="${esc(v)}" aria-label="${esc(v)} ချက်နည်းများ ကြည့်ရန်">${esc(v)}</button>`).join('')}</div>`}
function bindFacets(){document.querySelectorAll('[data-facet]').forEach(b=>b.onclick=()=>{state[b.dataset.facet]=normalizeName(b.dataset.value);state.query='';state.category='all';state.time='';state.difficulty='';$('#dialog').open&&$('#dialog').close();shell();$('#collection').scrollIntoView({behavior:'smooth'})})}
function iconsNow(){createIcons({icons,attrs:{'stroke-width':1.7}})}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),5500)}
function fail(error){console.error(error);toast(api.errorMessage(error))}
function photo(r,hero=false){const cover=recipePhotos(r)[0]||'';return `<div class="food-image ${hero?'hero-image':''}" style="--food-color:${({rice:'#e8c47e',noodle:'#d39d65',salad:'#97ac76',curry:'#d79764',dessert:'#d8b499'})[r.category]||'#bec69b'}"><div class="plate" aria-hidden="true"><span>${glyph[r.category]||'🍲'}</span></div>${cover||r.id==='egg-fried-rice'?`<img src="${esc(cover||'/images/fried-rice-illustration.png')}" alt="${esc(title(r))}${!cover?' — illustration':''}" ${hero?'fetchpriority="high"':'loading="lazy"'} referrerpolicy="no-referrer">`:''}</div>`}
function bindImages(){document.querySelectorAll('.food-image img').forEach(img=>{img.onerror=()=>img.remove()})}
function shell(){clearInterval(heroTimer);document.documentElement.lang=state.lang;$('#app').innerHTML=`
<div class="top-note">${i('sprout')} ${tr('From our kitchens, with love.','မီးဖိုချောင်မှ မေတ္တာဖြင့်')} <span>${tr('A little taste of home, every day.','နေ့စဉ် အိမ်ချက်အရသာ')}</span></div>
<header class="header"><a href="#" class="brand" aria-label="Myanmar Kitchen home"><span class="brand-mark">${i('cooking-pot')}</span><span>Myanmar<span class="brand-bottom">KITCHEN <b>•</b> မြန်မာမီးဖိုချောင်</span></span></a><nav aria-label="Main navigation"><button class="nav-item ${state.view==='discover'?'active':''}" data-view="discover">${tr('Discover','ရှာဖွေရန်')}</button><button class="nav-item ${state.view==='saved'?'active':''}" data-view="saved">${i('heart')}${tr('My cookbook','သိမ်းထားသည်')}</button></nav><div class="header-actions"><button class="language" id="language" aria-label="Switch language">${state.lang==='en'?'မြန်မာ':'English'}</button><button class="user-button" id="account">${i('user-round')}<span>${esc(state.user?.name||tr('Sign in','ဝင်ရန်'))}</span></button><button class="primary small" id="share">${i('plus')}<span>${tr('Share a recipe','ချက်နည်းမျှဝေ')}</span></button></div></header>
<main id="main" tabindex="-1">${state.view==='discover'?hero():`<section class="saved-intro"><span class="eyebrow">YOUR OWN LITTLE COLLECTION</span><h1>${tr('My cookbook','ကျွန်ုပ်၏ ဟင်းချက်စာအုပ်')}</h1><p>Keep the dishes you love close to hand.</p></section>`}
<section class="chatgpt-entry"><div><span class="eyebrow">CHATGPT → MYANMAR KITCHEN</span><h2>ChatGPT က ချက်နည်းကို အလွယ်သိမ်းမယ်</h2><p>ချက်နည်းမေးပါ။ ကြိုက်ရင် “Kitchen ထဲသိမ်းပေးပါ” လို့ပြောပါ။ ရလာတဲ့လင့်ခ်ကိုနှိပ်ပြီး သိမ်းနိုင်ပါမယ်။</p></div><button class="primary" id="chatgpt-start">ChatGPT နဲ့ ချက်နည်းယူရန်</button></section><section class="collection" id="collection"><div class="section-top"><div><span class="eyebrow">${tr('GOOD FOOD. EVERY DAY.','နေ့စဉ် အရသာကောင်း')}</span><h2>${state.view==='saved'?tr('Saved with love','သိမ်းထားသော ဟင်းများ'):tr('What shall we cook?','ဒီနေ့ ဘာချက်မလဲ?')}</h2></div><p class="section-note">${tr('A familiar favorite or a delicious new discovery.','နှစ်သက်ရာ ဟင်းချက်နည်းများကို ရှာဖွေပါ။')}</p></div>
<div class="search-line"><label class="search">${i('search')}<input id="search" type="search" value="${esc(state.query)}" placeholder="${tr('Search dishes, ingredients, cooks…','ဟင်းအမည်၊ ပါဝင်ပစ္စည်း၊ ချက်သူ ရှာရန်…')}" aria-label="Search recipes"><kbd>⌕</kbd></label><label class="select-label">${i('clock-3')}<select id="time" aria-label="Cooking time"><option value="">Any time</option><option value="15">15 min or less</option><option value="30">30 min or less</option><option value="60">60 min or less</option></select></label><label class="select-label"><select id="difficulty" aria-label="Difficulty"><option value="">Any difficulty</option><option value="easy">Easy</option><option value="medium">Medium</option><option value="hard">A little challenge</option></select></label></div>
<div class="categories" aria-label="Recipe categories"><button data-category="all" class="category ${state.category==='all'?'selected':''}">${i('utensils')} ${tr('Everything','အားလုံး')}</button>${categoryIds().map(c=>`<button data-category="${c}" class="category ${state.category===c?'selected':''}"><span>${glyph[c]||'🍽️'}</span> ${esc(label(c))}</button>`).join('')}</div>
<div class="variant-filters">${[['recipeGroup','ချက်နည်းအုပ်စု အားလုံး'],['region','ဒေသ / စတိုင် အားလုံး']].map(([key,text])=>`<label>${text}<select id="${key}" aria-label="${text}"><option value="">${text}</option>${facetValues(key).map(v=>`<option value="${esc(normalizeName(v))}">${esc(v)}</option>`).join('')}</select></label>`).join('')}</div><div class="results-top"><p id="count" role="status"></p><label class="sort">Sort by <select id="sort" aria-label="Sort recipes"><option value="featured">Kitchen picks</option><option value="quick">Quickest first</option><option value="name">Name A–Z</option></select></label></div><div id="grid" class="grid"></div></section>
<section class="community"><div class="community-icon">${i('notebook-pen')}</div><div><span class="eyebrow">EVERY RECIPE HAS A STORY</span><h2>${tr('Your family favorite belongs here.','သင့်အိမ်ချက်နည်းကို မျှဝေပါ။')}</h2><p>A treasured curry. A clever shortcut. A little kitchen wisdom.<br>Share something good with the community.</p></div><button class="primary" id="community-share">${tr('Share your recipe','ချက်နည်း မျှဝေရန်')} ${i('arrow-up-right')}</button></section></main>
<footer><div class="footer-top"><div><a href="#" class="brand footer-brand">${i('cooking-pot')} Myanmar Kitchen</a><p>Home cooking. Shared stories. Happy hearts.<br>A community table with room for everyone.</p></div><div class="support"><span class="eyebrow">HELP KEEP THE KITCHEN WARM</span><div>${[['coffee','Coffee','coffee'],['burger','Burger','sandwich'],['big_meal','Big Meal','soup'],['charity','Donation / Charity','hand-heart']].map(([key,text,icon])=>safeUrl(api.supportUrl(key))?`<a data-support-link="${key}" href="${esc(safeUrl(api.supportUrl(key)))}" target="_blank" rel="noopener noreferrer">${i(icon)} ${text}</a>`:`<button data-support="${key}">${i(icon)} ${text}</button>`).join('')}</div></div></div><div class="footer-bottom"><span>Made by MM <span class="heart">♥</span> · © ${new Date().getFullYear()}</span><div><button data-policy="privacy">Privacy</button><button data-policy="terms">Terms</button><button id="admin">${i('shield-check')} Admin</button></div></div></footer><nav class="mobile-nav" aria-label="Mobile navigation"><button data-view="discover">${i('compass')}Discover</button><button data-view="saved">${i('heart')}Cookbook</button><button id="mobile-share">${i('circle-plus')}Share</button><button id="mobile-account">${i('user-round')}Profile</button></nav>`;
 $('#search').oninput=e=>{state.query=e.target.value;renderGrid()};for(const field of ['time','difficulty','sort','recipeGroup','region']){$('#'+field).value=state[field];$('#'+field).onchange=e=>{state[field]=e.target.value;renderGrid()}}
 document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{state.category=b.dataset.category;document.querySelectorAll('[data-category]').forEach(x=>x.classList.toggle('selected',x===b));renderGrid()});
 document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{state.view=b.dataset.view;state.query='';state.category='all';state.recipeGroup='';state.region='';shell()});
 document.querySelectorAll('.brand').forEach(a=>a.onclick=e=>{e.preventDefault();state.view='discover';shell();window.scrollTo({top:0,behavior:'smooth'})});
 $('#language').onclick=()=>{state.lang=state.lang==='en'?'my':'en';localStorage.setItem('mykitch_lang',state.lang);shell()};
 for(const id of ['share','community-share','mobile-share'])$('#'+id).onclick=()=>submission();for(const id of ['account','mobile-account'])$('#'+id).onclick=()=>account();
 $('#chatgpt-start').onclick=chatgptStart;$('#admin').onclick=()=>admin();document.querySelectorAll('[data-policy]').forEach(b=>b.onclick=()=>policy(b.dataset.policy));document.querySelectorAll('[data-support]').forEach(b=>b.onclick=()=>support(b.dataset.support));
 $('#browse')?.addEventListener('click',()=>$('#collection').scrollIntoView({behavior:'smooth'}));$('#today')?.addEventListener('click',()=>detail(heroRecipe()));
 renderGrid();iconsNow();bindImages();startHero();if(api.dataWarning){const n=document.createElement('p');n.className='notice';n.textContent=api.dataWarning;$('#collection').prepend(n)}}
function hero(){const r=heroRecipe();return `<section class="hero"><div class="hero-copy"><span class="eyebrow"><span class="little-line"></span> ${tr('A TASTE OF HOME','အိမ်ချက်အရသာ')}</span><h1>${tr('A little inspiration.<br>A lot of <em>comfort.</em>','အိမ်ချက်အရသာနဲ့<br><em>နွေးထွေးသောနေ့ရက်များ</em>')}</h1><p>${tr('From everyday rice dishes to the treats we grew up with.<br>Discover, cook, and share the flavors that bring us together.','နေ့စဉ်ဟင်းလျာများမှ ရိုးရာမုန့်များအထိ<br>အတူတူ ရှာဖွေ၊ ချက်ပြုတ်၊ မျှဝေကြမယ်။')}</p><button id="browse" class="primary">${tr('Find your next favorite','နှစ်သက်ရာဟင်း ရှာရန်')} ${i('arrow-right')}</button><div class="hero-proof"><div class="mini-avatars"><span>👩🏻‍🍳</span><span>👨🏽‍🍳</span><span>👩🏽‍🌾</span></div><span>Made for home cooks.<br><strong>Better when shared.</strong></span></div></div><div class="hero-showcase"><button class="hero-feature" id="today" aria-label="${esc(tr('Open recipe: ','ချက်နည်းကြည့်ရန်: ')+title(r))}">${heroSlide(r)}</button>${heroRecipes().length>1?'<button class="hero-pause secondary small" id="hero-pause"></button>':''}</div></section>`}
function renderGrid(){const grid=$('#grid');if(state.loading){grid.innerHTML='<p class="empty">Gathering recipes…</p>';$('#count').textContent='Loading';return}if(state.error){grid.innerHTML=`<div class="empty"><h3>The kitchen is taking a moment.</h3><p>${esc(state.error)}</p><button id="retry" class="primary">Try again</button></div>`;$('#retry').onclick=load;return}
 if(state.view==='saved'&&!state.user){grid.innerHTML='<div class="empty"><h3>A cookbook of your own</h3><p>Sign in to save your favorites across devices.</p><button class="primary" id="saved-login">Sign in with Google</button></div>';$('#saved-login').onclick=()=>account();$('#count').textContent='Your favorites live here';return}
 let list=state.recipes.filter(r=>(state.view!=='saved'||state.favorites.has(r.id))&&(state.category==='all'||r.category===state.category)&&(!state.recipeGroup||normalizeName(r.recipeGroup)===state.recipeGroup)&&(!state.region||normalizeName(r.region)===state.region)&&(!state.time||(r.cookTime>0&&r.cookTime<=Number(state.time)))&&(!state.difficulty||r.difficulty===state.difficulty)&&matchesRecipe({...r,tags:[...r.tags,categoryRecord(r.category)?.name||'',categoryRecord(r.category)?.nameMy||'']},state.query));if(state.sort==='quick')list.sort((a,b)=>(a.cookTime||9999)-(b.cookTime||9999));if(state.sort==='name')list.sort((a,b)=>title(a).localeCompare(title(b)));
 $('#count').textContent=`${list.length} ${tr('recipes to make your day','ချက်နည်းများ')}`;grid.innerHTML=list.length?list.map(r=>`<article class="recipe-card"><div class="card-visual"><button class="image-button" data-open="${esc(r.id)}" aria-label="Open ${esc(title(r))}">${photo(r)}</button><span class="card-tag">${esc(label(r.category))}</span><button class="favorite ${state.favorites.has(r.id)?'is-saved':''}" data-favorite="${esc(r.id)}" aria-label="${state.favorites.has(r.id)?'Unsave':'Save'} ${esc(title(r))}" aria-pressed="${state.favorites.has(r.id)}">${i('heart')}</button></div><div class="card-body"><div class="card-meta">${i('clock-3')} ${r.cookTime?`${r.cookTime} min`:'Time not added'} <span>·</span> ${complete(r)?esc(r.difficulty):'Community draft'}</div><button class="card-title" data-open="${esc(r.id)}">${esc(title(r))}</button><p class="burmese">${esc(state.lang==='en'?r.nameMy:r.name)}</p>${variantBadges(r)}<p class="card-description">${esc(description(r))}</p><div class="card-author"><span>${i('chef-hat')} ${esc(r.author)}</span><button class="card-open" data-open="${esc(r.id)}" aria-label="${esc(title(r))} ချက်နည်းကြည့်ရန်">${i('arrow-up-right')}</button></div></div></article>`).join(''):`<div class="empty"><span class="empty-emoji">🍲</span><h3>${state.view==='saved'?'Your cookbook is waiting.':'No recipes on this shelf yet.'}</h3><p>${state.view==='saved'?'Tap the heart on a recipe to save it here.':'Try another ingredient or clear your filters.'}</p><button id="clear" class="secondary">Clear filters</button></div>`;
 $('#clear')?.addEventListener('click',()=>{Object.assign(state,{query:'',category:'all',recipeGroup:'',region:'',time:'',difficulty:''});shell()});document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>detail(state.recipes.find(r=>r.id===b.dataset.open)));document.querySelectorAll('[data-favorite]').forEach(b=>b.onclick=()=>toggleFavorite(b.dataset.favorite,b));iconsNow();bindImages();bindFacets();}
async function toggleFavorite(id,button){if(!state.user){account();return}button.disabled=true;try{const on=!state.favorites.has(id);await api.favorite(state.user.uid,id,on);on?state.favorites.add(id):state.favorites.delete(id);renderGrid();toast(on?'Added to your cookbook.':'Removed from your cookbook.')}catch(e){fail(e)}finally{button.disabled=false}}
function modal(html){disposeDialog();disposeDialog=()=>{};const d=$('#dialog');d.innerHTML=`<button class="close" aria-label="Close dialog">${i('x')}</button>${html}`;if(!d.open)d.showModal();d.querySelector('.close').onclick=()=>d.close();iconsNow();bindImages()}
function detail(r,notice=''){if(!r)return;const ingredients=state.lang==='my'&&r.ingredientsMy?.length?r.ingredientsMy:r.ingredients;const steps=state.lang==='my'&&r.stepsMy?.length?r.stepsMy:r.steps;modal(`<div class="detail-photo">${photo(r)}</div>${photoGallery(r)}<div class="dialog-body">${notice?`<p class="notice" role="status">${esc(notice)}</p>`:''}<div class="recipe-language"><button data-recipe-lang="my" class="secondary" aria-pressed="${state.lang==='my'}">မြန်မာ</button><button data-recipe-lang="en" class="secondary" aria-pressed="${state.lang==='en'}">English</button></div><span class="eyebrow">${esc(label(r.category))} · ${esc(r.region||'Myanmar')}</span><h2 id="dialog-title">${esc(title(r))}</h2><p class="burmese">${esc(state.lang==='en'?r.nameMy:r.name)}</p><p>${esc(description(r))}</p>${variantBadges(r)}<div class="detail-facts"><span>${i('clock-3')} ${r.cookTime?`${r.cookTime} min`:'Time needed'}</span><span>${i('users')} ${r.servings?`${r.servings} servings`:'Servings needed'}</span><span>${i('chart-no-axes-column')} ${esc(r.difficulty)}</span></div><p class="muted">By ${esc(r.author)} ${r.lastContributor?`· Updated with help from ${esc(r.lastContributor)}`:''}</p>${!complete(r)?'<p class="notice">This recipe was preserved from the original collection. Ingredients and steps are still needed—help us complete it.</p>':''}<div class="recipe-columns"><section><h3>${tr('Ingredients & measurements','ပါဝင်ပစ္စည်းနှင့် အချိုးအစား')}</h3>${ingredients.length?ingredients.map(x=>`<label class="ingredient"><input type="checkbox"><span>${esc(x)}</span></label>`).join(''):'<p>Not added yet.</p>'}</section><section><h3>${tr('Let’s make it','ပြုလုပ်နည်း')}</h3><ol class="steps">${steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol></section></div>${r.tags?.length?`<div class="tags">${r.tags.map(t=>`<span>#${esc(t)}</span>`).join('')}</div>`:''}${r.videos?.length?`<h3>From the contributor’s kitchen</h3><div class="videos">${r.videos.map(video=>{const v=videoPreview(video);return v?`<div class="video-link">${v.embed?`<button class="secondary play-video" data-embed="${esc(v.embed)}">${i('play')} Load YouTube video</button>`:''}<a href="${esc(v.url)}" target="_blank" rel="noopener noreferrer">${i('external-link')} Watch on ${esc(v.host)}</a></div>`:''}).join('')}</div><p class="muted">Videos load only when you choose to play. Other services open in a new tab.</p>`:''}<div class="dialog-actions"><button class="primary" id="detail-save">${i('heart')} ${state.favorites.has(r.id)?'Saved · remove':'Save to cookbook'}</button><button class="secondary" id="edit">${i('pencil')} ${canEditRecipe(r,state.user)?tr('Edit recipe','ချက်နည်း ပြင်ရန်'):tr('Suggest an edit','ပြင်ဆင်ချက် အကြံပြုရန်')}</button><button class="secondary" id="copy">${i('link')} Copy link</button></div></div>`);bindFacets();bindPhotoGallery(r);document.querySelectorAll('[data-recipe-lang]').forEach(button=>button.onclick=()=>{state.lang=button.dataset.recipeLang;localStorage.setItem('mykitch_lang',state.lang);shell();detail(r)});$('#edit').onclick=()=>submission(r);$('#detail-save').onclick=async e=>{await toggleFavorite(r.id,e.currentTarget);if(state.user)detail(r)};$('#copy').onclick=async()=>{try{await navigator.clipboard.writeText(`${location.origin}${location.pathname}#recipe/${encodeURIComponent(r.id)}`);toast('Recipe link copied.')}catch{toast('Copy this address: '+location.origin+'/#recipe/'+r.id)}};document.querySelectorAll('.play-video').forEach(b=>b.onclick=()=>{const f=document.createElement('iframe');f.src=b.dataset.embed;f.title='Contributor recipe video';f.allowFullscreen=true;f.referrerPolicy='strict-origin-when-cross-origin';f.setAttribute('sandbox','allow-scripts allow-same-origin allow-presentation');b.replaceWith(f)})}
async function account(){if(!state.user){modal(`<div class="dialog-body sign-in"><span class="modal-illustration">🍵</span><span class="eyebrow">THERE'S A PLACE FOR YOU HERE</span><h2 id="dialog-title">Welcome to the kitchen.</h2><p>Save recipes you love, share your family favorites, and help our community cookbook grow.</p><button class="primary" id="google">${i('log-in')} Continue with Google</button><p id="auth-error" class="form-error" role="alert"></p>${!api.configured?'<p class="notice">Google login အတွက် app-config.json ထဲတွင် Firebase web configuration ထည့်ရန် လိုအပ်ပါသည်။</p>':''}<p class="muted">By continuing, you agree to our Terms and Privacy policy.</p></div>`);$('#google').onclick=async e=>{e.currentTarget.disabled=true;try{await api.login();$('#dialog').close()}catch(error){if($('#auth-error'))$('#auth-error').textContent=api.authMessage(error);else fail(error)}finally{if($('#google'))$('#google').disabled=false}};return}
 const u=state.user;modal(`<div class="dialog-body"><span class="eyebrow">YOUR KITCHEN CORNER</span><h2 id="dialog-title">Hello, ${esc(u.name)}.</h2><p class="muted">${esc(u.email)}</p><form id="profile"><label>Display name<input name="name" required maxlength="80" value="${esc(u.name)}"></label><label>A little about your cooking<textarea name="bio" maxlength="500">${esc(u.bio)}</textarea></label><button class="primary">Save profile</button></form><div class="dialog-actions"><button class="secondary" id="account-chatgpt">ChatGPT နဲ့ ချက်နည်းယူရန်</button><button class="secondary" id="account-bulk">အစုလိုက်ထည့်ရန်</button><button class="secondary" id="mine">My contributions</button>${u.admin?'<button class="secondary" id="review-inbox">Admin inbox</button>':''}<button class="secondary" id="signout">Sign out</button></div></div>`);$('#profile').onsubmit=async e=>{e.preventDefault();const data=new FormData(e.target);await busy(e.target,async()=>{const name=data.get('name').trim();if(!name)throw new Error('Please add your name.');await api.profile(u.uid,name,data.get('bio').trim());Object.assign(u,{name,bio:data.get('bio').trim()});shell();toast('Profile updated.')})};$('#signout').onclick=async()=>{try{await api.logout();$('#dialog').close()}catch(e){fail(e)}};$('#account-chatgpt').onclick=chatgptStart;$('#account-bulk').onclick=bulkImport;$('#mine').onclick=()=>inbox(false);$('#review-inbox')?.addEventListener('click',()=>inbox(true));}
function field(name,label,value='',type='text',extra=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`}
function area(name,label,value='',required=false){return `<label>${label}<textarea name="${name}" ${required?'required':''} rows="4">${esc(value)}</textarea></label>`}
function submission(r,draft=false,fromImport=false){if(!state.user){account();return}const isEdit=Boolean(r)&&!draft,directEdit=isEdit&&canEditRecipe(r,state.user);modal(`<div class="dialog-body"><span class="eyebrow">A LITTLE KNOW-HOW GOES A LONG WAY</span><h2 id="dialog-title">${isEdit?(directEdit?'ချက်နည်း ပြင်ရန်':'Suggest a better recipe'):'Share something delicious'}</h2><p>အသစ်နှင့် ကိုယ်တင်ထားသောချက်နည်း ပြင်ဆင်မှုများ ချက်ချင်းသိမ်းပါမည်။ သူတစ်ပါး၏ချက်နည်းကို အကြံပြုပြင်ခြင်းသာ Admin အတည်ပြုချက်လိုပါသည်။</p><form id="recipe-form"><div class="form-save-panel"><p id="form-error" class="form-error" role="alert"></p><button class="primary" id="submit-recipe">${isEdit?(directEdit?'ပြင်ဆင်ချက် သိမ်းရန်':'Send edit request'):'ချက်နည်းကို ထုတ်ဝေသိမ်းရန်'} ${i('arrow-right')}</button></div><div class="form-row">${field('name','Recipe name / English',r?.name,'text','required maxlength="160"')}${field('nameMy','မြန်မာအမည် (optional)',r?.nameMy,'text','maxlength="160"')}</div><div id="duplicate" role="status" aria-live="polite"></div>${area('description','A short introduction',r?.description,true)}${area('descriptionMy','မြန်မာ မိတ်ဆက် (optional)',r?.descriptionMy)}<div class="form-row"><label>Category<select name="category">${categoryIds().map(c=>`<option value="${c}" ${r?.category===c?'selected':''}>${esc(label(c))}</option>`).join('')}</select></label><label>Difficulty<select name="difficulty">${['easy','medium','hard'].map(x=>`<option ${r?.difficulty===x?'selected':''}>${x}</option>`).join('')}</select></label></div>${state.user.admin?categoryPanel():''}<div class="form-row">${field('cookTime','Total prep + cook time (minutes)',r?.cookTime||30,'number','min="1" max="1440" required')}${field('servings','Servings',r?.servings||2,'number','min="1" max="100" required')}</div>${area('ingredients','Ingredients with measurements · one per line',r?.ingredients?.join('\n'),true)}${area('steps','Preparation & cooking steps · one per line',r?.steps?.join('\n'),true)}<details><summary>Add Burmese ingredients & steps</summary>${area('ingredientsMy','ပါဝင်ပစ္စည်းများ',r?.ingredientsMy?.join('\n'))}${area('stepsMy','ပြုလုပ်နည်း',r?.stepsMy?.join('\n'))}</details><div class="form-row">${field('recipeGroup','ချက်နည်းအုပ်စု (optional)',r?.recipeGroup,'text','maxlength="80" list="recipe-groups" placeholder="ဥပမာ မုန့်တီ"')}<datalist id="recipe-groups">${[...new Set(['မုန့်တီ',...facetValues('recipeGroup')])].map(v=>`<option value="${esc(v)}"></option>`).join('')}</datalist>${field('region','ဒေသ / စတိုင် (optional)',r?.region,'text','maxlength="100" list="recipe-regions" placeholder="ဥပမာ ရခိုင်"')}<datalist id="recipe-regions">${facetValues('region').map(v=>`<option value="${esc(v)}"></option>`).join('')}</datalist></div><p class="muted">အုပ်စုတူ မျိုးကွဲများအတွက် အုပ်စုအမည်တူ ရွေးပါ။ ဥပမာ အုပ်စု “မုန့်တီ”၊ ချက်နည်းအမည် “ရခိုင်မုန့်တီ”။ အုပ်စုအသစ် အကြံပြုနိုင်ပြီး Admin အတည်ပြုမှ ရှာဖွေစာရင်းတွင် ပေါ်ပါမည်။</p><div class="form-row">${field('tags','Tags · comma separated',r?.tags?.join(', '))}</div><section class="photo-picker"><label for="photo-file">ဖုန်း / ကွန်ပျူတာမှ ဓာတ်ပုံ ၃ ပုံအထိ ရွေးရန်</label><input id="photo-file" type="file" multiple accept="image/jpeg,image/png,image/webp,image/gif,image/avif,image/heic,image/heif,.heic,.heif"><p class="muted">JPG, PNG, WebP, GIF, AVIF, HEIC/HEIF · 25 MB အထိ။ ပုံကို အများဆုံး 1600 px / 600 KB အထိ အလိုအလျောက်ချုံ့ပေးပါမည်။ GIF သည် ပုံငြိမ်အဖြစ် သိမ်းပါမည်။</p><div id="photo-preview"></div><p id="photo-status" role="status"></p><button type="button" class="secondary" id="remove-photo">ပုံဖယ်ရှားရန်</button></section>${field('photo','သို့မဟုတ် Photo URL · HTTPS (optional)',r?.photo,'url')}${area('photos','ပုံလင့်ခ်များ · ၃ ပုံအထိ၊ တစ်ကြောင်းတစ်ပုံ',r?.photos?.join('\n'))}${area('videos','YouTube, TikTok or other video URLs · one per line',r?.videos?.join('\n'))}${area('note',isEdit&&!directEdit?'What should change, and why?':'မှတ်ချက် (optional)','',isEdit&&!directEdit)}<p class="muted">Only share text, images and videos you own or have permission to share. Empty photo? We’ll add a cheerful kitchen illustration.</p></form></div>`);
 const form=$('#recipe-form');let photoBusy=false,pendingPhotos=[],uploadedUrls=[],previewUrls=[],photoVersion=0,coverIndex=0;const revokePreviews=()=>{previewUrls.forEach(url=>URL.revokeObjectURL(url));previewUrls=[]};disposeDialog=()=>{photoVersion++;revokePreviews()};$('#dialog').addEventListener('close',()=>disposeDialog(),{once:true});function check(){const dupe=duplicateOf(state.recipes,{name:form.elements.name.value,nameMy:form.elements.nameMy.value},draft?undefined:r?.id);$('#duplicate').innerHTML=dupe?`<div class="notice"><strong>Already in the cookbook: ${esc(dupe.name)}</strong><p>Help improve the existing recipe instead of adding a duplicate.</p><button type="button" id="view-existing" class="secondary">View existing recipe</button><button type="button" id="edit-existing" class="primary small">Request a change</button></div>`:'';$('#submit-recipe').disabled=Boolean(dupe)||photoBusy;$('#view-existing')?.addEventListener('click',()=>detail(dupe));$('#edit-existing')?.addEventListener('click',()=>submission(dupe));return dupe}form.elements.name.oninput=check;form.elements.nameMy.oninput=check;

 if(state.user.admin)bindCategoryPanel(category=>{const option=document.createElement('option');option.value=category.id;option.textContent=label(category.id);form.elements.category.append(option);form.elements.category.value=category.id;});
 function renderPhotoChoices(urls){$('#photo-preview').innerHTML=urls.map((url,index)=>`<button type="button" class="photo-choice ${index===coverIndex?'selected':''}" data-cover-index="${index}" aria-pressed="${index===coverIndex}"><img src="${esc(url)}" alt="ရွေးထားသောပုံ ${index+1}"><span>${index===coverIndex?'အဖုံးပုံ':'အဖုံးပုံအဖြစ် ရွေးရန်'}</span></button>`).join('');form.querySelectorAll('[data-cover-index]').forEach(button=>button.onclick=()=>{coverIndex=Number(button.dataset.coverIndex);if(!pendingPhotos.length)form.elements.photo.value=urls[coverIndex];renderPhotoChoices(urls)})}
 $('#photo-file').onchange=async e=>{const files=[...e.target.files];if(!files.length)return;if(files.length>3){$('#photo-status').textContent='တစ်ကြိမ်လျှင် ပုံ ၃ ပုံအထိ ရွေးပါ။';e.target.value='';return}const version=++photoVersion;photoBusy=true;check();pendingPhotos=[];uploadedUrls=[];form.elements.photo.readOnly=true;$('#photo-status').textContent='ပုံများကို ချုံ့နေပါသည်…';revokePreviews();$('#photo-preview').replaceChildren();try{const results=[];for(const file of files)results.push(await compressPhoto(file));if(version!==photoVersion||!form.isConnected)return;pendingPhotos=results.map(result=>result.blob);previewUrls=pendingPhotos.map(blob=>URL.createObjectURL(blob));coverIndex=0;renderPhotoChoices(previewUrls);$('#photo-status').textContent=`ပုံ ${pendingPhotos.length} ပုံ အသင့်ဖြစ်ပါပြီ။ အဖုံးပုံကို ရွေးနိုင်ပါသည်။`;}catch(error){if(version===photoVersion&&form.isConnected){$('#photo-status').textContent=error.message;form.elements.photo.readOnly=false}}finally{if(version===photoVersion&&form.isConnected){photoBusy=false;check()}}};
 form.insertAdjacentHTML('beforeend',`<fieldset><legend>ရွေးသုံးနိုင်သော AI နမူနာပုံများ</legend><p>မူရင်းဟင်းလျာဓာတ်ပုံ မဟုတ်ပါ။ ကြိုက်သည့်ပုံကို ရွေးပါ။</p><div class="sample-photos">${[['laphet-ai-sample.png','လက်ဖက်သုပ်'],['mont-lone-ai-sample.png','မုန့်လုံးရေပေါ်']].map(([file,name])=>`<button type="button" data-sample-photo="${file}"><img src="/images/${file}" alt="${name} AI နမူနာ" width="140"><span>${name}</span></button>`).join('')}</div></fieldset>`);
 form.querySelectorAll('[data-sample-photo]').forEach(button=>button.onclick=()=>{$('#remove-photo').click();const url=new URL('/images/'+button.dataset.samplePhoto,location.protocol==='https:'?location.origin:'https://kitchen.mmusa.org').href;form.elements.photo.value=url;form.elements.photos.value=url;$('#photo-status').textContent='AI နမူနာပုံ ရွေးပြီးပါပြီ။';renderPhotoChoices([url]);check()});
 $('#remove-photo').onclick=()=>{photoVersion++;photoBusy=false;pendingPhotos=[];uploadedUrls=[];revokePreviews();$('#photo-preview').replaceChildren();$('#photo-status').textContent='';$('#photo-file').value='';form.elements.photo.value='';form.elements.photos.value='';form.elements.photo.readOnly=false;check()};
 const initialPhotos=recipePhotos(r);if(initialPhotos.length)renderPhotoChoices(initialPhotos);
 form.elements.photos.onchange=()=>{if(!pendingPhotos.length){const urls=form.elements.photos.value.split('\n').map(x=>x.trim()).filter(url=>safeUrl(url)).slice(0,3);coverIndex=0;if(urls.length)form.elements.photo.value=urls[0];renderPhotoChoices(urls)}};

 check();
 form.onsubmit=async e=>{e.preventDefault();if(photoBusy||check())return;const raw=Object.fromEntries(new FormData(form));for(const key of ['ingredients','ingredientsMy','steps','stepsMy','videos','photos'])raw[key]=raw[key].split('\n').map(x=>x.trim()).filter(Boolean);raw.tags=raw.tags.split(',').map(x=>x.trim()).filter(Boolean);const controls=[...form.querySelectorAll('input,select,textarea,button')];controls.forEach(c=>c.disabled=true);await busy(form,async()=>{try{const recipe=validateRecipe(raw,categoryIds());if(pendingPhotos.length){for(let index=0;index<pendingPhotos.length;index++){if(!uploadedUrls[index]){if(form.isConnected)$('#photo-status').textContent=`ပုံ ${index+1} / ${pendingPhotos.length} သိမ်းနေပါသည်…`;const uploaded=await api.call('uploadRecipePhoto',{base64:await base64Of(pendingPhotos[index])});uploadedUrls[index]=uploaded.url}}recipe.photos=[...uploadedUrls];recipe.photo=uploadedUrls[coverIndex];if(form.isConnected)$('#photo-status').textContent='ပုံများ သိမ်းပြီးပါပြီ။'}const result=await api.call('submitRecipe',{recipe,targetId:!draft&&r?.id||null,baseVersion:isEdit?(r.version||0):0,note:raw.note});if(draft||fromImport){clearImportDraft();history.replaceState(null,'',result.recipeId?'#recipe/'+encodeURIComponent(result.recipeId):location.pathname)}await load();modal(`<div class="dialog-body sign-in"><span class="modal-illustration">💌</span><h2 id="dialog-title">A little goodness, on its way.</h2><p>${isEdit?(result.status==='published'?'ပြင်ဆင်ချက် သိမ်းပြီးပါပြီ။':'ပြင်ဆင်ချက်ပို့ပြီးပါပြီ။ Admin အတည်ပြုရန် စောင့်နေပါသည်။'):'ချက်နည်းအသစ် ထုတ်ဝေပြီးပါပြီ။'}</p><button class="primary" id="open-submissions">တင်ထားသောစာရင်း ကြည့်ရန်</button></div>`);$('#open-submissions').onclick=()=>inbox(Boolean(state.user?.admin))}catch(error){if(error.details?.recipeId){await load();const existing=state.recipes.find(x=>x.id===error.details.recipeId);if(existing){detail(existing);toast('This name already exists. Choose Suggest an edit.');return}}if(form.isConnected)form.querySelector('#form-error').textContent=api.errorMessage(error,'submitRecipe');throw error}});controls.forEach(c=>c.disabled=false);if(form.isConnected)check();};}
async function busy(form,action){const b=form.querySelector('button[type="submit"],button.primary');b.disabled=true;try{await action()}catch(e){fail(e)}finally{b.disabled=false}}
function admin(){if(!state.user){account();return}if(!state.user.admin){modal('<div class="dialog-body"><h2 id="dialog-title">The review kitchen</h2><p>This page is for appointed administrators. Your account does not have admin access.</p></div>');return}inbox(true)}
async function inbox(review){modal('<div class="dialog-body"><h2 id="dialog-title">Loading contributions…</h2></div>');try{const entries=await api.requests(state.user);modal(`<div class="dialog-body"><span class="eyebrow">${review?'COMMUNITY REVIEW':'YOUR CONTRIBUTIONS'}</span><h2 id="dialog-title">${review?'The review inbox':'From your kitchen'}</h2><p>${review?'User တင်ထားသော recipe အသစ်နှင့် ပြင်ဆင်ချက်များကို ရွေးဖွင့်ပြီး အတည်ပြုထုတ်ဝေပါ သို့မဟုတ် ပယ်ချပါ။':'Follow your submissions and edit requests here.'}</p>${review?adminActions():''}<div class="admin-tabs"><button data-inbox-filter="all">အားလုံး (${entries.length})</button><button data-inbox-filter="submission">အသစ်တင်ထားသည် (${entries.filter(x=>x.type==='submission'&&x.status==='pending').length})</button><button data-inbox-filter="edit">ပြင်ဆင်ချက် (${entries.filter(x=>x.type==='edit'&&x.status==='pending').length})</button><button data-inbox-filter="approved">အတည်ပြုပြီး</button><button data-inbox-filter="rejected">ပယ်ချပြီး</button></div><p id="filter-empty" hidden>ဒီစာရင်းမှာ မရှိသေးပါ။</p><div class="request-list">${entries.length?entries.map(x=>`<button class="request-row" data-request="${x.id}" data-type="${x.type}" data-status="${x.status}"><span><strong>${esc(x.recipe.name)}</strong><small>${esc(x.type)} · ${esc(x.author)}</small></span><span class="status ${x.status}">${esc(x.status)}</span></button>`).join(''):'<div class="empty"><h3>တင်ထားသော Request မရှိသေးပါ။</h3><p>အပေါ်က Recipe အသစ်တင်ရန် ခလုတ်ကို သုံးနိုင်ပါသည်။ ပို့မအောင်မြင်သော request များ ဒီစာရင်းထဲ မရောက်သေးပါ။</p></div>'}</div></div>`);bindAdminActions();document.querySelectorAll('[data-inbox-filter]').forEach(b=>b.onclick=()=>{const f=b.dataset.inboxFilter;let visible=0;document.querySelectorAll('[data-request]').forEach(row=>{row.hidden=!(f==='all'||row.dataset.status===f||row.dataset.type===f&&row.dataset.status==='pending');if(!row.hidden)visible++});$('#filter-empty').hidden=visible>0;document.querySelectorAll('[data-inbox-filter]').forEach(x=>x.classList.toggle('selected',x===b))});document.querySelectorAll('[data-request]').forEach(b=>b.onclick=()=>reviewDetail(entries.find(x=>x.id===b.dataset.request),review))}catch(e){modal(`<div class="dialog-body"><h2 id="dialog-title">Inbox ဖွင့်မရသေးပါ</h2><p role="alert">${esc(api.errorMessage(e,'inbox'))}</p><p class="muted">Firestore rules မတင်ပြီးသေးလျှင် ZIP ထဲက deployment လမ်းညွှန်အတိုင်း rules ကို အရင်တင်ပါ။</p><button id="retry-inbox" class="primary">Try again</button></div>`);$('#retry-inbox').onclick=()=>inbox(review)}}
function reviewDetail(x,review){const current=state.recipes.find(r=>r.id===x.targetId);const fields=['photos','name','nameMy','description','descriptionMy','category','difficulty','cookTime','servings','ingredients','ingredientsMy','steps','stepsMy','tags','recipeGroup','region','photo','videos'];const content=r=>fields.map(k=>`<div class="review-field"><strong>${esc(k)}</strong><p>${esc(Array.isArray(r[k])?r[k].join('\n'):r[k])||'—'}</p></div>`).join('');modal(`<div class="dialog-body"><span class="eyebrow">${esc(x.type)} · ${esc(x.status)}</span><h2 id="dialog-title">${esc(x.recipe.name)}</h2><p>Contributed by ${esc(x.author)}</p><p class="notice">${esc(x.note)||'No contributor note.'}</p><div class="review-columns">${current?`<section><h3>Current recipe</h3>${content(current)}</section>`:''}<section><h3>Proposed recipe</h3>${content(x.recipe)}</section></div>${x.reviewNote?`<p class="notice">Reviewer: ${esc(x.reviewNote)}</p>`:''}${review&&x.status==='pending'?'<form id="review-form"><label>Reviewer feedback<textarea name="note" maxlength="2000"></textarea></label><div class="dialog-actions"><button class="primary" type="button" id="approve">Approve & publish</button><button class="danger" type="button" id="reject">Reject</button></div><p id="review-error" role="alert"></p></form>':''}<button class="secondary" id="back-inbox">Back to inbox</button></div>`);$('#back-inbox').onclick=()=>inbox(review);for(const decision of ['approve','reject'])$('#'+decision)?.addEventListener('click',async()=>{const form=$('#review-form');form.querySelectorAll('button').forEach(b=>b.disabled=true);try{await api.call('reviewRequest',{id:x.id,decision,note:form.elements.note.value});await load();await inbox(true);toast(decision==='approve'?'Approved and published.':'Request rejected.')}catch(e){$('#review-error').textContent=api.errorMessage(e,'reviewRequest');fail(e);form.querySelectorAll('button').forEach(b=>b.disabled=false)}})}
function support(key){const names={coffee:'Coffee',burger:'Burger',big_meal:'Big Meal',charity:'Donation / Charity'};const url=safeUrl(api.supportUrl(key));modal(`<div class="dialog-body sign-in"><span class="modal-illustration">${key==='charity'?'💚':'☕'}</span><h2 id="dialog-title">${names[key]}</h2><p>Thank you for helping keep this community kitchen warm.</p>${url?`<a class="primary" href="${esc(url)}" target="_blank" rel="noopener noreferrer">Continue to ${names[key]} ${i('external-link')}</a>`:'<p class="notice">ငွေလက်ခံမည့် link မထည့်ရသေးပါ။ Coffee / Burger / Big Meal / Charity အတွက် link များ ထည့်ပြီးမှ ငွေပေးချေမှုစာမျက်နှာကို ဖွင့်နိုင်ပါမည်။</p>'}</div>`)}
function policy(which){modal(`<div class="dialog-body policy"><h2 id="dialog-title">${which==='privacy'?'Privacy':'Community terms'}</h2>${which==='privacy'?'<p>When connected, Myanmar Kitchen uses Google sign-in through Firebase. Your profile name, email, account identifier, saved recipes and contributions are processed to provide your account and community features.</p><h3>What is shared</h3><p>Published recipes show your display name. Favorites and profile records are private to your account; submissions are visible to you and administrators. Do not include private information in contributions.</p><h3>Other services</h3><p>Uploaded recipe photos are stored in Firebase Storage and can be viewed by anyone with their shareable download link. Recipe photos may also load from external image providers. Video players load only after you choose to play them. External links and support providers have their own privacy policies. Your language preference is stored on this device.</p><h3>Your choices</h3><p>You can edit your profile, remove favorites and sign out. For account or contribution removal, contact the site operator through the channel where you found this app. The operator must publish a direct support contact before public launch.</p>':'<p>Share useful, respectful cooking content that you own or have permission to publish. By submitting, you allow the site operator to display and moderate it with contributor credit.</p><h3>Community review</h3><p>New recipes publish immediately after sign-in. Authors can edit their own recipes immediately, and administrators can edit any recipe. Other contributors can suggest changes for administrator approval. Exact duplicate names are not accepted; suggest a change to the existing recipe instead. Administrators may reject inaccurate, unsafe, unrelated or infringing content.</p><h3>In your kitchen</h3><p>Recipes are community contributions. Check ingredients for allergies and follow appropriate food handling practices. Older entries may be incomplete and are marked accordingly.</p><h3>Support</h3><p>Support payments are optional and handled by the linked provider. No payment is required to browse or contribute. Charity destinations are chosen by the site operator.</p>'}</div>`)}
async function load(){state.loading=true;state.error='';if($('#grid'))renderGrid();try{const [recipes,cats]=await Promise.all([api.recipes(),api.getCategories().catch(()=>state.customCategories)]);state.recipes=recipes;state.customCategories=cats}catch(e){state.error='Recipes could not be loaded. Check your connection or Firebase configuration.';console.error(e)}finally{state.loading=false;shell()}}
async function boot(){shell();try{await api.start(async(user,error)=>{const userChanged=state.user?.uid!==user?.uid;state.user=user;authReady=true;state.favorites=new Set();shell();if(error)fail(error);if(user){try{const uid=user.uid;const fav=await api.favorites(uid);if(state.user?.uid===uid)state.favorites=fav}catch(e){fail(e)}}shell();if(!state.loading){if(userChanged&&importDraft&&$('#dialog .import-preview')&&location.hash.startsWith(IMPORT_PREFIX))showImportPreview();else await openImportRoute()}});await load();await openImportRoute();if(location.hash==='#chatgpt')chatgptStart();const id=decodeURIComponent(location.hash.replace('#recipe/',''));if(location.hash.startsWith('#recipe/'))detail(state.recipes.find(r=>r.id===id));}catch(e){state.loading=false;state.error=e.message;shell()}}
boot();
window.addEventListener('hashchange',()=>{if(location.hash==='#chatgpt'){chatgptStart();return}if(location.hash.startsWith(IMPORT_PREFIX)){importRouteShown='';openImportRoute();return}if(location.hash.startsWith('#recipe/'))detail(state.recipes.find(r=>r.id===decodeURIComponent(location.hash.slice(8))))});

function categoryPanel(){return `<details class="category-panel"><summary>＋ Category အသစ်ထည့်ရန် (Admin)</summary><label>အမည် / English<input id="category-name" maxlength="80"></label><label>မြန်မာအမည် (optional)<input id="category-name-my" maxlength="80"></label><button type="button" class="secondary" id="add-category">Category သိမ်းရန်</button><p id="category-status" role="status"></p></details>`}
function bindCategoryPanel(onCreated){$('#add-category').onclick=async e=>{const button=e.currentTarget;button.disabled=true;const name=$('#category-name').value,nameMy=$('#category-name-my').value;try{const category=await api.call('createCategory',{name,nameMy});state.customCategories.push(category);$('#category-name').value='';$('#category-name-my').value='';$('#category-status').textContent='Category အသစ် သိမ်းပြီးပါပြီ။';onCreated(category);shell()}catch(error){$('#category-status').textContent=api.errorMessage(error,'createCategory')}finally{button.disabled=false}}}
function manageCategories(){if(!state.user?.admin)return;modal(`<div class="dialog-body"><h2 id="dialog-title">Category များ စီမံရန်</h2><p>ထည့်ထားသော category များကို လူတိုင်း၏ filter နှင့် recipe form တွင် အသုံးပြုနိုင်ပါမည်။</p><div id="category-list" class="tags">${categoryIds().map(id=>`<span>${esc(label(id))}</span>`).join('')}</div>${categoryPanel()}</div>`);$('#dialog details').open=true;bindCategoryPanel(category=>{const item=document.createElement('span');item.textContent=label(category.id);$('#category-list').append(item)})}

function adminActions(){return `<div class="admin-actions"><button class="primary" id="inbox-new">＋ Recipe အသစ်တင်ရန်</button><button class="secondary" id="inbox-refresh">စာရင်းပြန်ဖတ်ရန်</button><button class="secondary" id="published-list">ရှိပြီးသား Recipe များ ပြင်ရန်</button><button class="secondary" id="manage-categories">Category များ စီမံရန်</button><button class="secondary" id="bulk-import">အစုလိုက်ထည့်ရန်</button><button class="secondary" id="catalog-setup">မူလချက်နည်းများ ချိတ်ဆက်ရန်</button></div><p id="inbox-action-status" role="status"></p>`}
function bindAdminActions(){
 $('#bulk-import')?.addEventListener('click',bulkImport);
 $('#manage-categories')?.addEventListener('click',manageCategories);$('#inbox-new')?.addEventListener('click',()=>submission());$('#inbox-refresh')?.addEventListener('click',()=>inbox(true));$('#published-list')?.addEventListener('click',publishedList);
 $('#catalog-setup')?.addEventListener('click',async e=>{const b=e.currentTarget;b.disabled=true;try{await api.call('initializeCatalog',{});await load();$('#inbox-action-status').textContent='မူလချက်နည်းများ ချိတ်ဆက်ပြီးပါပြီ။'}catch(e){$('#inbox-action-status').textContent=api.errorMessage(e,'initializeCatalog')}finally{b.disabled=false}});
}
function publishedList(){if(!state.user?.admin)return;modal(`<div class="dialog-body"><h2 id="dialog-title">ရှိပြီးသား Recipe များ</h2><p>ပြင်လိုသော recipe ကို ရွေးပါ။ သိမ်းလိုက်လျှင် ချက်ချင်းပြောင်းပါမည်။</p><div class="request-list">${state.recipes.map(r=>`<button class="request-row" data-edit-recipe="${esc(r.id)}">${esc(title(r))} ${i('pencil')}</button>`).join('')}</div><button class="secondary" id="return-inbox">Admin စာရင်းသို့</button></div>`);document.querySelectorAll('[data-edit-recipe]').forEach(b=>b.onclick=()=>submission(state.recipes.find(r=>r.id===b.dataset.editRecipe)));$('#return-inbox').onclick=()=>inbox(true)}

function bulkImport(){
 if(!state.user){account();return}
 modal(`<div class="dialog-body"><h2 id="dialog-title">ချက်နည်းများ အစုလိုက်ထည့်ရန်</h2><p>JSON ဖိုင်ရွေးပါ သို့မဟုတ် စာရင်းကူးထည့်ပါ။ အမည်တူများကို ကျော်မည်။</p><button id="bulk-sample" class="secondary">အသင့်ချက်နည်း ၆ မျိုး ရွေးရန်</button><input id="bulk-file" type="file" accept=".json,application/json"><textarea id="bulk-data" rows="10" aria-label="ချက်နည်း JSON"></textarea><button id="bulk-check" class="secondary">အရင်စစ်ကြည့်ရန်</button><div id="bulk-preview"></div><button id="bulk-publish" class="primary" disabled>စစ်ပြီးသောချက်နည်းများ ထည့်ရန်</button><p id="bulk-status" role="status"></p></div>`);
 let ready=[];
 const invalidate=()=>{ready=[];$('#bulk-publish').disabled=true;$('#bulk-preview').replaceChildren()};
 $('#bulk-sample').onclick=async()=>{try{const response=await fetch('/recipe-pack.json');if(!response.ok)throw new Error('ချက်နည်းဖိုင် ဖတ်မရပါ။');$('#bulk-data').value=JSON.stringify(await response.json(),null,2);$('#bulk-check').click()}catch(e){$('#bulk-status').textContent=e.message}};
 $('#bulk-data').oninput=invalidate;
 $('#bulk-file').onchange=async e=>{invalidate();try{if(e.target.files[0].size>2000000)throw new Error('ဖိုင်သည် 2 MB အောက်ဖြစ်ရပါမည်။');$('#bulk-data').value=await e.target.files[0].text()}catch(e){$('#bulk-status').textContent=e.message}};
 $('#bulk-check').onclick=()=>{invalidate();try{const data=JSON.parse($('#bulk-data').value);if(!Array.isArray(data)||!data.length||data.length>100)throw new Error('တစ်ကြိမ်လျှင် ၁ မှ ၁၀၀ အထိ JSON array ထည့်ပါ။');const seen=[...state.recipes];const rows=[];for(const [index,input] of data.entries()){try{const recipe=validateRecipe(input,categoryIds());if(duplicateOf(seen,recipe)){rows.push(`${index+1}. ${recipe.name} — ရှိပြီးသား၊ ကျော်မည်`);continue}seen.push(recipe);ready.push(recipe);rows.push(`${index+1}. ${recipe.name} — အသင့်`)}catch(e){rows.push(`${index+1}. ${e.message}`)}}$('#bulk-preview').innerHTML=rows.map(x=>`<p>${esc(x)}</p>`).join('');$('#bulk-publish').disabled=!ready.length;$('#bulk-status').textContent=`ထည့်ရန် ${ready.length} မျိုး အသင့်ဖြစ်ပါပြီ။`}catch(e){$('#bulk-status').textContent=e.message}};
 $('#bulk-publish').onclick=async()=>{const controls=[$('#bulk-sample'),$('#bulk-publish'),$('#bulk-check'),$('#bulk-data'),$('#bulk-file')];controls.forEach(x=>x.disabled=true);const status=$('#bulk-status');let count=0,error='';for(const recipe of ready){status.textContent=`${count+1} / ${ready.length} ထည့်နေပါသည်…`;try{await api.call('submitRecipe',{recipe});count++}catch(e){if(e.code==='functions/already-exists'){count++;continue}error=api.errorMessage(e);break}}ready=ready.slice(count);await load();status.textContent=`${count} မျိုး ပြီးပါပြီ။ ${ready.length} မျိုး ကျန်ပါသည်။ ${error}`;controls.forEach(x=>x.disabled=false);$('#bulk-publish').disabled=!ready.length;};
}

function chatgptStart(){
 modal(`<div class="dialog-body"><span class="eyebrow">CHATGPT → KITCHEN</span><h2 id="dialog-title">ဘာချက်ချင်လဲ၊ ဘာမုန့်လုပ်ချင်လဲ?</h2><p><ol class="chatgpt-howto"><li>ဟင်းအမည်ထည့်ပြီး ChatGPT မှာ ဆက်မေးပါ။ ChatGPT ပေါ်လာရင် <strong>Send</strong> ကို နှိပ်ပါ။</li><li>ChatGPT အဖြေထဲက <strong>Kitchen ထဲသိမ်းရန်</strong> လင့်ခ်ကို နှိပ်ပါ။</li><li>Kitchen စာမျက်နှာအပေါ်က <strong>ချက်နည်းကို ထုတ်ဝေသိမ်းရန်</strong> ကို နှိပ်ပါ။ နာမည်တူရင် ကိုယ့်လက်ရာအဖြစ် သီးခြားသိမ်းနိုင်ပါသည်။</li></ol></p><form id="chatgpt-dish-form"><label>ဟင်း / မုန့်အမည်<input id="chatgpt-dish" maxlength="160" placeholder="ဥပမာ မုန့်လုံးရေပေါ်" required></label><button class="primary" type="submit">ChatGPT မှာ ဆက်မေးရန်</button></form><p class="muted">လင့်ခ်ထုတ်ရန် ChatGPT ၏ code execution လုပ်ဆောင်ချက် လိုပါသည်။ သီးခြား AI API key မလိုပါ။</p><details><summary>ရှိပြီးသား ChatGPT စကားဝိုင်းမှာ သုံးရန်</summary><p>ဒီညွှန်ကြားချက်ကို တစ်ကြိမ်သာ ထည့်ထားပါ။ နောက်ချက်နည်းများအတွက် စာကူးရန် မလိုပါ။</p><button class="secondary" id="copy-chatgpt-instructions">ချိတ်ဆက်ညွှန်ကြားချက် ကူးရန်</button><p id="chatgpt-copy-status" role="status"></p></details></div>`);
 $('#chatgpt-dish-form').onsubmit=e=>{e.preventDefault();const dish=$('#chatgpt-dish').value.trim();if(!dish)return;window.open('https://chatgpt.com/?q='+encodeURIComponent(recipeChatPrompt(dish)),'_blank','noopener,noreferrer')};
 $('#copy-chatgpt-instructions').onclick=async()=>{try{await navigator.clipboard.writeText(recipeChatPrompt());$('#chatgpt-copy-status').textContent='ကူးပြီးပါပြီ။ ChatGPT စကားဝိုင်းထဲ တစ်ကြိမ်ပို့ပါ။'}catch{$('#chatgpt-copy-status').textContent='Browser မှ clipboard ခွင့်ပြုရန် လိုပါသည်။'}};
}

function clearImportDraft(){importDraft=null}
function rememberImportDraft(recipe){importDraft=recipe}
async function openImportRoute(){
 const hash=location.hash;
 if(!hash.startsWith(IMPORT_PREFIX)||!authReady||state.loading||importBusy||importRouteShown===hash)return;
 importBusy=true;
 try{
  const recipe=await decodeRecipeLink(hash);rememberImportDraft(recipe);importRouteShown=hash;showImportPreview();
 }catch(e){importRouteShown=hash;modal(`<div class="dialog-body"><h2 id="dialog-title">ချက်နည်းလင့်ခ် ဖွင့်မရပါ</h2><p role="alert">${esc(e.message)}</p><button class="secondary" id="import-retry">ပြန်စမ်းရန်</button></div>`);$('#import-retry').onclick=()=>{importRouteShown='';openImportRoute()}}
 finally{importBusy=false}
}
function showImportPreview(){
 const r=importDraft;if(!r)return;const ingredients=state.lang==='my'&&r.ingredientsMy?.length?r.ingredientsMy:r.ingredients,steps=state.lang==='my'&&r.stepsMy?.length?r.stepsMy:r.steps;
 const duplicate=duplicateOf(state.recipes,r);
 modal(`<div class="dialog-body import-preview"><span class="eyebrow">CHATGPT မှ ချက်နည်းရရှိပါပြီ</span><div class="import-action-panel"><div id="import-duplicate">${duplicate?`<p class="notice">ဒီအမည်နဲ့ ချက်နည်းရှိပြီးသားပါ။ အဟောင်းကို ပြင်သိမ်းရန် သို့မဟုတ် နာမည်ပြောင်း၍ အသစ်သိမ်းရန် ရွေးပါ။</p><button class="secondary" id="import-existing">ရှိပြီးသားချက်နည်း ကြည့်ရန်</button>${state.user?`<p class="muted">ဝင်ထားသူ: ${esc(state.user.email||state.user.name)} · မူလတင်သူ: ${esc(duplicate.author||'Home cook')}</p>${canEditRecipe(duplicate,state.user)?'<button class="primary" id="import-update-existing">ရှိပြီးသားကို ဒီချက်နည်းဖြင့်ပြင်ရန်</button>':'<p class="muted">အဟောင်းကို ပြင်ရန် မူလတင်ထားသောအကောင့် သို့မဟုတ် Admin အကောင့်ဖြင့် ဝင်ပါ။</p>'}<button class="${canEditRecipe(duplicate,state.user)?'secondary':'primary'}" id="import-variant">ကိုယ့်လက်ရာအဖြစ် အသစ်သိမ်းရန်</button><button class="secondary" id="import-rename">အမည်ကို ကိုယ်တိုင်ပြောင်းရန်</button>`:'<button class="primary" id="import-duplicate-login">Google ဖြင့်ဝင်ပြီး ရွေးချယ်ရန်</button>'}`:''}</div><div class="dialog-actions">${!duplicate?`<button class="primary" id="import-save">${state.user?'ချက်နည်းကို ထုတ်ဝေသိမ်းရန်':'Google ဖြင့်ဝင်ပြီး သိမ်းရန်'}</button><button class="secondary" id="import-adjust">ပုံရွေးရန် / စာပြင်ရန်</button>`:''}<button class="secondary" id="import-cancel">မသိမ်းတော့ပါ</button></div><p id="import-status" role="status"></p><details class="import-login-help"><summary>Login / သိမ်းရန် အခက်အခဲရှိလျှင်</summary><p>ChatGPT အတွင်းမှ ဖွင့်ထားသော browser တွင် Google login မရလျှင် ဒီလင့်ခ်ကို Safari သို့မဟုတ် Chrome မှာ ဖွင့်ပါ။ ချက်နည်းစာကို ကူးရန် မလိုပါ။</p><button class="secondary" id="import-copy-link">Browser မှာဖွင့်ရန် လင့်ခ်ကူးရန်</button><p id="import-copy-status" role="status"></p></details></div><div class="recipe-language"><button class="secondary" data-import-lang="my" aria-pressed="${state.lang==='my'}">မြန်မာ</button><button class="secondary" data-import-lang="en" aria-pressed="${state.lang==='en'}">English</button></div><h2 id="dialog-title">${esc(title(r))}</h2><p>${esc(description(r))}</p>${!r.descriptionMy||!r.ingredientsMy?.length||!r.stepsMy?.length?'<p class="notice">ဒီလင့်ခ်မှာ ဘာသာပြန်တစ်မျိုး မပြည့်စုံသေးပါ။ ChatGPT ကို “English နဲ့ မြန်မာ နှစ်ဘာသာလုံးပါတဲ့ Kitchen လင့်ခ် ပြန်ထုတ်ပေးပါ” လို့ပြောနိုင်ပါသည်။</p>':''}${importPhotoChoices(r)}<p class="notice">မသိမ်းရသေးပါ။ အောက်ပါအကြောင်းအရာကို စစ်ပြီးမှ ထုတ်ဝေပါ။</p><div class="detail-facts"><span>${r.cookTime} မိနစ်</span><span>လူ ${r.servings} ယောက်စာ</span></div><h3>${tr('Ingredients','ပါဝင်ပစ္စည်းများ')}</h3><ul>${ingredients.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3>${tr('Instructions','ပြုလုပ်နည်း')}</h3><ol class="steps">${steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol></div>`);
 document.querySelectorAll('[data-import-lang]').forEach(button=>button.onclick=()=>{state.lang=button.dataset.importLang;showImportPreview()});
 document.querySelectorAll('[data-import-cover]').forEach(button=>button.onclick=()=>{importDraft.photo=button.dataset.importCover;showImportPreview()});
 $('#import-copy-link').onclick=async()=>{try{await navigator.clipboard.writeText(location.href);$('#import-copy-status').textContent='လင့်ခ်ကူးပြီးပါပြီ။ Safari / Chrome မှာ ဖွင့်ပါ။'}catch{$('#import-copy-status').textContent='Browser ၏ Share / Open in browser ကို သုံးပါ။'}};
 $('#import-duplicate-login')?.addEventListener('click',importLogin);
 $('#import-variant')?.addEventListener('click',()=>{try{rememberImportDraft(importVariantRecipe(r,state.user,state.recipes));showImportPreview()}catch(error){$('#import-status').textContent=error.message}});
 $('#import-rename')?.addEventListener('click',()=>{submission({...r},true);$('#recipe-form').insertAdjacentHTML('afterbegin','<p class="notice">အသစ်အဖြစ်သိမ်းမည်။ English အမည်နှင့် မြန်မာအမည် နှစ်ခုလုံးကို ရှိပြီးသားနှင့် မတူအောင် ပြောင်းပါ။ အဟောင်းကို မပြောင်းပါ။</p>');$('#recipe-form [name=name]').focus()});
 $('#import-update-existing')?.addEventListener('click',()=>{const existing=duplicate;submission({...existing,...r,id:existing.id,authorId:existing.authorId,version:existing.version,photo:r.photo||existing.photo||'',photos:r.photos?.length?r.photos:(existing.photos||[])},false,true);});
 $('#import-existing')?.addEventListener('click',()=>detail(duplicate));
 $('#import-cancel').onclick=()=>{clearImportDraft();history.replaceState(null,'',location.pathname+location.search);$('#dialog').close()};
 $('#import-adjust')?.addEventListener('click',()=>{if(!state.user){importLogin();return}submission(importDraft,true)});
 $('#import-save')?.addEventListener('click',async e=>{if(!state.user){await importLogin();return}const button=e.currentTarget;button.disabled=true;$('#import-adjust').disabled=true;$('#import-cancel').disabled=true;try{const result=await api.call('submitRecipe',{recipe:r});clearImportDraft();history.replaceState(null,'',result.recipeId?'#recipe/'+encodeURIComponent(result.recipeId):location.pathname);await load();const saved=state.recipes.find(x=>x.id===result.recipeId);if(saved)detail(saved,'ချက်နည်းကို အောင်မြင်စွာ ထုတ်ဝေသိမ်းပြီးပါပြီ။');else $('#dialog').close();toast('ချက်နည်း ထုတ်ဝေသိမ်းပြီးပါပြီ။')}catch(error){if(error.details?.recipeId){await load();showImportPreview()}if($('#import-status'))$('#import-status').textContent=api.errorMessage(error);button.disabled=false;if($('#import-adjust'))$('#import-adjust').disabled=false;if($('#import-cancel'))$('#import-cancel').disabled=false}});
}
async function importLogin(){try{await api.login();importRouteShown='';await openImportRoute()}catch(error){if($('#import-status'))$('#import-status').textContent=api.authMessage(error);else fail(error)}}

function photoGallery(recipe){const photos=recipePhotos(recipe);return photos.length>1?`<div class="recipe-gallery" aria-label="Recipe photo gallery">${photos.map((url,index)=>`<button class="gallery-thumb ${index===0?'is-chosen':''}" data-gallery-photo="${esc(url)}" aria-label="ပုံ ${index+1} ကြည့်ရန်"><img src="${esc(url)}" alt="${esc(title(recipe))} — ပုံ ${index+1}" loading="lazy" referrerpolicy="no-referrer"></button>`).join('')}</div>`:''}
function bindPhotoGallery(recipe){document.querySelectorAll('[data-gallery-photo]').forEach(button=>button.onclick=()=>{$('#dialog .detail-photo').innerHTML=photo({...recipe,photo:button.dataset.galleryPhoto,photos:[button.dataset.galleryPhoto]});document.querySelectorAll('[data-gallery-photo]').forEach(other=>other.classList.toggle('is-chosen',other===button));bindImages()})}
function importPhotoChoices(recipe){const photos=recipePhotos(recipe);if(!photos.length)return '<p class="notice">ဒီလင့်ခ်မှာ ပုံမပါသေးပါ။ ChatGPT မှ ပုံများကို သိမ်းယူပြီး “ပုံရွေးရန် / စာပြင်ရန်” မှ ပုံ ၃ ပုံအထိ တစ်ခါတည်း ရွေးတင်နိုင်ပါသည်။</p>';return `<fieldset><legend>ပုံ ${photos.length} ပုံ ပါရှိပါသည် · အဖုံးပုံရွေးရန်</legend><div class="import-photo-choices">${photos.map((url,index)=>`<button type="button" class="photo-choice ${index===0?'selected':''}" data-import-cover="${esc(url)}" aria-pressed="${index===0}"><img src="${esc(url)}" alt="ချက်နည်းပုံ ${index+1}" referrerpolicy="no-referrer"><span>${index===0?'အဖုံးပုံ':'အဖုံးပုံအဖြစ် ရွေးရန်'}</span></button>`).join('')}</div><p class="muted">ရွေးထားသော ပုံများအားလုံးကို သိမ်းပြီး အဖုံးပုံကို အရှေ့တွင်ပြပါမည်။</p></fieldset>`}
